def choose_move(observation):
    w = observation['grid_width']
    h = observation['grid_height']
    x, y = observation['self_position']
    data = observation.get('resources', [])
    obstacles = set(observation.get('obstacles', []))
    res_count = observation.get('remaining_resource_count', 0)
    score_self = observation.get('scores', [])[0]
    dir_map = {(-1,0):'L',(1,0):'R',(0,-1):'U',(0,1):'D'}
    # Try to find resource nearby
    for dx, dy in dir_map:
        nx, ny = x+dx, y+dy
        if 0<=nx<w and 0<=ny<h and (nx,ny) in data:
            return [dx,dy]
    # Else move towards resource if exists
    min_dist = None
    target_move = None
    for dx, dy in dir_map:
        nx, ny = x+dx, y+dy
        if 0<=nx<w and 0<=ny<h and (nx,ny) not in obstacles:
            for rx, ry in data:
                dist = abs(rx - nx)+abs(ry - ny)
                if min_dist is None or dist < min_dist:
                    min_dist = dist
                    target_move = [dx,dy]
    if target_move:
        return target_move
    # Else move randomly avoiding obstacles
    for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
        nx, ny = x+dx, y+dy
        if 0<=nx<w and 0<=ny<h and (nx,ny) not in obstacles:
            return [dx,dy]
    # Stay still if no move possible
    return [0,0]
